20	import org.springframework.stereotype.Service;
21	import org.springframework.transaction.annotation.Transactional;
22	import org.springframework.web.server.ResponseStatusException;
23	
24	/**
25	 * The claims on a sheet: listed per person newest first, added, edited and moved through their
26	 * statuses one at a time. Only a DRAFT can be edited. A voided claim keeps
27	 * its number, which is never reused; a claim opened while period numbering is on is numbered within its
28	 * period instead of sheet-wide. Settling a claim fixes its due at the rate its person's grade has then on the claim's date
29	 * (at least the sheet's floor then), or at the
30	 * figure a statement bound it to, plus the late charge it has then. No claim dated inside a closed period can be added, edited or moved,
31	 * and no claim dated after its person's retirement date can be added or edited to that date. A clerk
32	 * settling a claim whose due is above the sheet's clerk limit leaves it PENDING instead; a steward settles
33	 * anything, and approves a PENDING claim (settling it, its due fixed then) or rejects it with a reason
34	 * (back to OPEN); the user who opened a claim cannot approve it. A claim
35	 * with a negative amount is a correction: it is added or edited only when it names, by number, a SETTLED
36	 * claim of the same person, and only a correction names one.
37	 */
38	@Service
39	public class ClaimService {
40	
41	    private final ClaimRepository claims;
42	    private final PersonRepository people;
43	    private final SheetService sheets;
44	    private final SheetRepository sheetRows;
45	    private final RateService rates;
46	    private final Rollup rollup;
47	    private final PeriodService periods;
48	    private final AccessService access;
49	    private final ApplicationEventPublisher events;
50	
51	    public ClaimService(ClaimRepository claims, PersonRepository people, SheetService sheets,
52	            SheetRepository sheetRows, RateService rates, Rollup rollup, PeriodService periods, AccessService access,
53	            ApplicationEventPublisher events) {
54	        this.access = access;
55	        this.rollup = rollup;
56	        this.periods = periods;
57	        this.claims = claims;
58	        this.people = people;
59	        this.sheets = sheets;
60	        this.sheetRows = sheetRows;
61	        this.rates = rates;
62	        this.events = events;
63	    }
64	
65	    /** Every claim on the sheet by the person who made it, each person's newest first. */
66	    @Transactional(readOnly = true)
67	    public Map<Long, List<Claim>> bySheet(String sheetId) {
68	        return claims.findBySheetIdOrderByListedDesc(sheetId).stream()
69	                .collect(Collectors.groupingBy(Claim::getPersonId));
70	    }
71	
72	    @Transactional(readOnly = true)
73	    public List<Claim> forPerson(String sheetId, long personId) {
74	        return claims.findBySheetIdAndPersonIdOrderByListedDesc(sheetId, personId);
75	    }
76	
77	    /** Add a claim; a date left out takes the sheet's today. Returns the person it belongs to. */
78	    @Transactional
79	    public long add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note) {
80	        return add(sheetId, user, personId, amount, date, note, null);
81	    }
82	
83	    /**
84	     * Add a claim, a correction naming the number of the claim it corrects; a date left out takes the
85	     * sheet's today. Returns the person it belongs to.
86	     */
87	    @Transactional
88	    public long add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
89	            String corrects) {
90	        Person person = people.findByIdAndSheetId(personId, sheetId)
91	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
92	        LocalDate on = date != null ? date : sheets.today(sheetId);
93	        periods.requireOpen(sheetId, on);
94	        requireNotRetired(person, on);
95	        LocalDate correctsDate = requireCorrects(sheetId, personId, amount, corrects);
96	        Rollup.Figures before = rollup.figures(sheetId);
97	        Claim claim = new Claim(sheetId, personId, amount, on, note == null ? "" : note, corrects);
98	        claim.setCorrectsDate(correctsDate);
99	        claim.setDueBy(on.plusDays(sheets.load(sheetId, user).termsFor(person.gradeOn(on))));
100	        log(sheetId, user, claim, person);
101	        claims.saveAndFlush(claim);
102	        events.publishEvent(new ClaimChanged("CLAIM_ADDED", sheetId, user, person.getName(), amount, on, null, null));
103	        rollup.changed(sheetId, user, before);
104	        return personId;
105	    }
106	
107	    /**
108	     * Edit a claim's amount, date and note; only a DRAFT can be edited (an open claim is voided and
109	     * added again instead), and an edit is refused when a closed period contains its date or the new one.
110	     * Returns the person it belongs to.
111	     */
112	    @Transactional
113	    public long edit(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note,
114	            String corrects) {
115	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
116	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
117	        LocalDate on = date != null ? date : sheets.today(sheetId);
118	        periods.requireOpen(sheetId, claim.getDate(), on);
119	        if (claim.getStatus() != ClaimStatus.DRAFT) {
120	            throw new ResponseStatusException(HttpStatus.CONFLICT,
121	                    "A " + claim.getStatus() + " claim cannot be edited; void it and add a new one");
122	        }
123	        if (!on.equals(claim.getDate())) {
124	            people.findByIdAndSheetId(claim.getPersonId(), sheetId).ifPresent(p -> requireNotRetired(p, on));
125	        }
126	        LocalDate correctsDate = requireCorrects(sheetId, claim.getPersonId(), amount, corrects);
127	        Rollup.Figures before = rollup.figures(sheetId);
128	        claim.setAmount(amount);
129	        claim.setCorrects(corrects);
130	        claim.setCorrectsDate(correctsDate);
131	        claim.setDate(on);
132	        claim.setNote(note == null ? "" : note);
133	        claims.flush();
134	        String person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).map(Person::getName).orElse("");
135	        events.publishEvent(new ClaimChanged("CLAIM_EDITED", sheetId, user, person, claim.getAmount(),
136	                claim.getDate(), claim.getShownNumber(), null));
137	        rollup.changed(sheetId, user, before);
138	        return claim.getPersonId();
139	    }
140	
141	    /**
142	     * Move a claim to a status; a move its status does not allow, settling by the user who opened
143	     * the claim, or moving a claim dated inside a closed period, is refused and changes nothing. Settling
144	     * by a clerk a claim whose due is above the clerk limit leaves it PENDING.
145	     * Returns the person it belongs to.
146	     */
147	    @Transactional
148	    public long move(String sheetId, String user, long claimId, ClaimStatus next) {
149	        Claim claim = claim(sheetId, claimId);
150	        if (!claim.getStatus().canBecome(next)) {
151	            throw new ResponseStatusException(HttpStatus.CONFLICT,
152	                    "A " + claim.getStatus() + " claim cannot become " + next);
153	        }
154	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
155	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
156	                    "The user who opened a claim cannot settle it");
157	        }
158	        Rollup.Figures before = rollup.figures(sheetId);
159	        if (next == ClaimStatus.OPEN) {
160	            giveNumber(sheetId, claim);
161	            claim.setOpenedBy(user);
162	        }
163	        String number = claim.getShownNumber();
164	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null);
165	        String due = null;
166	        if (next == ClaimStatus.SETTLED) {
167	            BigDecimal fixed = dueNow(sheetId, claim, owner);
168	            if (access.canSettle(sheetId, user, fixed)) {
169	                claim.setSettledDue(fixed);
170	                due = fixed == null ? "n/a" : fixed.toPlainString();
171	            } else {
172	                next = ClaimStatus.PENDING;
173	            }
174	        }
175	        claim.setStatus(next);
176	        log(sheetId, user, claim, owner);
177	        claims.flush();
178	        String person = owner == null ? "" : owner.getName();
179	        String event = switch (next) {
180	            case OPEN -> "CLAIM_OPENED";
181	            case PENDING -> "CLAIM_PENDING";
182	            case SETTLED -> "CLAIM_SETTLED";
183	            case VOID -> "CLAIM_VOIDED";
184	            case DRAFT -> throw new IllegalStateException();
185	        };
186	        events.publishEvent(new ClaimChanged(event, sheetId, user, person, claim.getAmount(), claim.getDate(), number, due));
187	        rollup.changed(sheetId, user, before);
188	        return claim.getPersonId();
189	    }
190	
191	    /**
192	     * Approve a PENDING claim, settling it with its due fixed now (its live figure, late charge frozen in).
193	     * Only a steward approves, never the user who opened the claim; a claim not PENDING or dated inside a
194	     * closed period is refused and nothing changes. Returns the person it belongs to.
195	     */
196	    @Transactional
197	    public long approve(String sheetId, String user, long claimId) {
198	        Claim claim = pending(sheetId, user, claimId, "approve", "approved");
199	        if (user.equals(claim.getOpenedBy())) {
200	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot approve it");
201	        }
202	        Rollup.Figures before = rollup.figures(sheetId);
203	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null);
204	        BigDecimal fixed = dueNow(sheetId, claim, owner);
205	        claim.setSettledDue(fixed);
206	        claim.setStatus(ClaimStatus.SETTLED);
207	        log(sheetId, user, claim, owner);
208	        claims.flush();
209	        events.publishEvent(new ClaimChanged("CLAIM_APPROVED", sheetId, user, owner == null ? "" : owner.getName(),
210	                claim.getAmount(), claim.getDate(), claim.getShownNumber(), fixed == null ? "n/a" : fixed.toPlainString()));
211	        rollup.changed(sheetId, user, before);
212	        return claim.getPersonId();
213	    }
214	
215	    /**
216	     * Reject a PENDING claim with a reason, putting it back to OPEN (bound again by the last statement if
217	     * that statement counted it). Only a steward rejects; a claim not PENDING or dated inside a closed
218	     * period is refused and nothing changes. Returns the person it belongs to.
219	     */
220	    @Transactional
221	    public long reject(String sheetId, String user, long claimId, String reason) {
222	        Claim claim = pending(sheetId, user, claimId, "reject", "rejected");
223	        Rollup.Figures before = rollup.figures(sheetId);
224	        claim.setStatus(ClaimStatus.OPEN);
225	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null);
226	        log(sheetId, user, claim, owner);
227	        claims.flush();
228	        String person = owner == null ? "" : owner.getName();
229	        events.publishEvent(new ClaimChanged("CLAIM_REJECTED", sheetId, user, person, claim.getAmount(),
230	                claim.getDate(), claim.getShownNumber(), null, reason));
231	        rollup.changed(sheetId, user, before);
232	        return claim.getPersonId();
233	    }
234	
235	    /**
236	     * A steward moves a DRAFT, OPEN or PENDING claim to another person on the sheet. The claim keeps its
237	     * number and date, is released from any figure a statement bound it to (live again until its new
238	     * person's next statement), and lists as its new person's newest claim. A settled or voided claim, a
239	     * correction, a claim dated inside a closed period or after the new person's retirement date, or a move
240	     * by anyone but a steward is refused and nothing changes. Returns the people it moved from and to.
241	     */
242	    @Transactional
243	    public long[] reassign(String sheetId, String user, long claimId, long toPersonId) {
244	        Claim claim = claim(sheetId, claimId);
245	        if (access.roleOf(sheetId, user) != Role.STEWARD) {
246	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a steward can reassign a claim");
247	        }
248	        if (claim.getStatus() != ClaimStatus.DRAFT && claim.getStatus() != ClaimStatus.OPEN
249	                && claim.getStatus() != ClaimStatus.PENDING) {
250	            throw new ResponseStatusException(HttpStatus.CONFLICT,
251	                    "A " + claim.getStatus() + " claim cannot be reassigned");
252	        }
253	        if (claim.isCorrection()) {
254	            throw new ResponseStatusException(HttpStatus.CONFLICT,
255	                    "A correction belongs with the claim it corrects and cannot be reassigned");
256	        }
257	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
258	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
259	        Person to = people.findByIdAndSheetId(toPersonId, sheetId)
260	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT, "Choose a person on the sheet"));
261	        if (from.getId().equals(to.getId())) {
262	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is already " + to.getName() + "'s");
263	        }
264	        requireNotRetired(to, claim.getDate());
265	        Rollup.Figures before = rollup.figures(sheetId);
266	        claim.setPersonId(to.getId());
267	        claim.unbind();
268	        claims.flush();
269	        claims.relist(claim.getId());
270	        events.publishEvent(new ClaimReassigned(sheetId, user, to.getName(), claim.getAmount(), claim.getDate(),
271	                claim.getShownNumber(), from.getName(), to.getName()));
272	        rollup.changed(sheetId, user, before);
273	        return new long[] { from.getId(), to.getId() };
274	    }
275	
276	    /** The PENDING claim a steward is to approve or reject; refused for anyone else or any other claim. */
277	    private Claim pending(String sheetId, String user, long claimId, String action, String done) {
278	        Claim claim = claim(sheetId, claimId);
279	        if (claim.getStatus() != ClaimStatus.PENDING) {
280	            throw new ResponseStatusException(HttpStatus.CONFLICT,
281	                    "A " + claim.getStatus() + " claim cannot be " + done + "; only a PENDING one can");
282	        }
283	        if (access.roleOf(sheetId, user) != Role.STEWARD) {
284	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a steward can " + action + " a claim");
285	        }
286	        return claim;
287	    }
288	
289	    private Claim claim(String sheetId, long claimId) {
290	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
291	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
292	        periods.requireOpen(sheetId, claim.getDate());
293	        return claim;
294	    }
295	
296	    /** Log the status a claim has just taken, on the sheet's today, with its due as it is now. */
297	    private void log(String sheetId, String user, Claim claim, Person owner) {
298	        BigDecimal due = owner == null ? (Dues.bound(claim) ? claim.getStatedDue() : claim.getSettledDue())
299	                : Dues.figure(claim, owner::gradeOn, rates.table(sheetId));
300	        claim.logStatus(user, sheets.today(sheetId), due);
301	    }
302	
303	    /** The claim's due now, its late charge frozen in, as settling fixes it. */
304	    private BigDecimal dueNow(String sheetId, Claim claim, Person owner) {
305	        return owner == null ? (Dues.bound(claim) ? claim.getStatedDue() : null)
306	                : Dues.figure(claim, owner::gradeOn, rates.table(sheetId));
307	    }
308	
309	    /**
310	     * Give a claim being opened its number: while the sheet's period numbering from is set and the
311	     * sheet's today is on or after it, the next in the period its date falls in (<period name>-<n>), or
312	     * in the sequence of claims in no period (X-<n>); otherwise the next sheet-wide number. Two users
313	     * taking one at the same moment wait on each other, so no number is given twice or skipped.
314	     */
315	    private void giveNumber(String sheetId, Claim claim) {
316	        LocalDate from = sheets.periodNumberingFrom(sheetId);
317	        if (from == null || sheets.today(sheetId).isBefore(from)) {
318	            claim.setNumber(sheets.nextClaimNumber(sheetId));
319	            return;
320	        }
321	        sheetRows.lockById(sheetId);
322	        Period period = periods.list(sheetId).stream().filter(p -> p.contains(claim.getDate()))
323	                .findFirst().orElse(null);
324	        String sequence = period == null ? "X" : "P" + period.getId();
325	        int n = claims.lastInSequence(sheetId, sequence) + 1;
326	        claim.setPeriodNumber(sequence, n, (period == null ? "X" : period.getName()) + "-" + n);
327	    }
328	
329	    /**
330	     * Refuse a correction (a negative amount) that does not name the number of a SETTLED claim of the
331	     * same person, and a claim that is not a correction but names one. Returns the date of the claim a
332	     * correction corrects (its rounding goes by it); null for any other claim.
333	     */
334	    private LocalDate requireCorrects(String sheetId, long personId, BigDecimal amount, String corrects) {
335	        if (amount.signum() >= 0) {
336	            if (corrects != null) {
337	                throw new ResponseStatusException(HttpStatus.CONFLICT,
338	                        "Only a correction (a negative amount) names a claim it corrects");
339	            }
340	            return null;
341	        }
342	        if (corrects == null) {
343	            throw new ResponseStatusException(HttpStatus.CONFLICT,
344	                    "A negative amount is a correction; name the number of the settled claim it corrects");
345	        }
346	        return claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId).stream()
347	                .filter(c -> corrects.equals(c.getShownNumber()) && c.getStatus() == ClaimStatus.SETTLED)
348	                .map(Claim::getDate).findFirst()
349	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT,
350	                        "Claim " + corrects + " is not a settled claim of this person"));
351	    }
352	
353	    /** Refuse a claim dated after its person's retirement date. */
354	    private static void requireNotRetired(Person person, LocalDate date) {
355	        if (person.isRetired() && date.isAfter(person.getRetiredFrom())) {
356	            throw new ResponseStatusException(HttpStatus.CONFLICT,
357	                    person.getName() + " is retired from " + person.getRetiredFrom()
358	                            + "; a claim cannot be dated after that");
359	        }
360	    }
361	}
